//! The compliance program. See docs/SPEC.md section 8.1.
//!
//! Phase 3 ships only the proof verification, behind `VerifyProof`, so the
//! Groth16 layer is tested on its own before clearances are built on top of it.

#![forbid(unsafe_code)]

pub mod error;
pub mod verify;
// Generated by snarkjs-bridge; kept byte-identical to its output so drift is detectable.
#[rustfmt::skip]
pub mod vk;

pub use error::ComplianceError;

/// Instruction tags.
pub mod tag {
    /// Verifies a withdraw proof and nothing else. Data: tag, a (64), b (128),
    /// c (64), then the four public inputs (32 each).
    pub const VERIFY_PROOF: u8 = 0;
}

#[cfg(not(feature = "no-entrypoint"))]
solana_program::entrypoint!(entry);

#[cfg(not(feature = "no-entrypoint"))]
fn entry(
    _program_id: &solana_program::pubkey::Pubkey,
    _accounts: &[solana_program::account_info::AccountInfo],
    data: &[u8],
) -> solana_program::entrypoint::ProgramResult {
    match data.split_first() {
        Some((&tag::VERIFY_PROOF, rest)) => {
            let req = verify::ProofRequest::decode(rest)?;
            verify::verify(&req)?;
            Ok(())
        }
        _ => Err(ComplianceError::UnknownInstruction.into()),
    }
}
